309	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
310	    @Override
311	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
312	        HttpHeaders headers = new HttpHeaders();
313	        Visit visit = visitMapper.toVisit(visitFieldsDto);
314	        Pet pet = new Pet();
315	        pet.setId(petId);
316	        visit.setPet(pet);
317	        this.clinicService.saveVisit(visit);
318	        VisitDto visitDto = visitMapper.toVisitDto(visit);
319	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
320	            .buildAndExpand(visit.getId()).toUri());
