324	
325	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
326	    @Override
327	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
328	        Owner owner = this.clinicService.findOwnerById(ownerId);
329	        if (owner != null) {
330	            Pet pet = owner.getPet(petId);
331	            if (pet != null) {
332	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
333	            }
334	        }
335	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
336	    }
337	
338	    private static boolean isBlank(String value) {
339	        return value == null || value.trim().isEmpty();
340	    }
341	
342	    /**
343	     * Normalize an owner identity field for household-duplicate comparison: trim, collapse every
344	     * run of whitespace to a single space, and lower-case. Used so that last name and address are
345	     * compared case-insensitively with collapsed whitespace.
346	     */
347	    private static String collapse(String value) {
348	        if (value == null) {
349	            return "";
350	        }
351	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
352	    }
353	
354	    /**
355	     * Common street-type abbreviations expanded during address normalization.
356	     */
357	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
358	        "ST", "STREET",
359	        "RD", "ROAD",
360	        "AVE", "AVENUE");
361	
362	    /**
363	     * Normalize an owner address into its canonical stored/compared form: trim, collapse every run
364	     * of whitespace to a single space, upper-case, and expand common street-type abbreviations
365	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). Returns an empty string for
366	     * a {@code null} or blank input. The transformation is idempotent, so an already-normalized
367	     * address maps to itself.
368	     */
369	    private static String normalizeAddress(String value) {
370	        if (value == null) {
371	            return "";
372	        }
373	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
374	        if (collapsed.isEmpty()) {
375	            return "";
376	        }
377	        String[] tokens = collapsed.split(" ");
378	        StringBuilder sb = new StringBuilder(collapsed.length());
379	        for (int i = 0; i < tokens.length; i++) {
380	            if (i > 0) {
381	                sb.append(' ');
382	            }
383	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
384	        }
385	        return sb.toString();
386	    }
387	
388	    /**
389	     * Derive the stable household identifier shared by owners with the same normalized last name
390	     * and address. It is a deterministic function of those two values, so every member of a
391	     * household independently derives the same identifier: the first 12 upper-case hex characters
392	     * of {@code SHA-256(normalizedLastName + '\n' + normalizedAddress)}.
393	     */
394	    private static String householdId(String normalizedLastName, String normalizedAddress) {
395	        try {
396	            byte[] digest = MessageDigest.getInstance("SHA-256")
397	                .digest((normalizedLastName + "\n" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
398	            StringBuilder sb = new StringBuilder(digest.length * 2);
399	            for (byte b : digest) {
400	                sb.append(String.format("%02x", b));
401	            }
402	            return sb.substring(0, 12).toUpperCase();
403	        }
404	        catch (NoSuchAlgorithmException e) {
405	            throw new IllegalStateException("SHA-256 not available", e);
406	        }
407	    }
408	
409	    /**
410	     * Derive the identity key into which all duplicate detection is consolidated:
411	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. A null email or
412	     * household id contributes an empty segment. Two owners are duplicates only when their whole
413	     * identity keys are equal.
414	     */
415	    private static String identityKey(String telephone, String email, String householdId) {
416	        return (telephone == null ? "" : telephone)
417	            + "|" + (email == null ? "" : email)
418	            + "|" + (householdId == null ? "" : householdId);
419	    }
420	
421	    /**
422	     * Build the customer code for a new owner: {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is the
423	     * upper-cased first three letters of the city, LAST3 the upper-cased first three letters of the
424	     * last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more than the
425	     * number of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
426	     */
427	    /**
428	     * Count the existing owners that share the given first and last name, compared
429	     * case-insensitively. Called before the new owner is saved, so the returned value reflects the
430	     * namesakes that already existed at creation time (the new owner itself is not included).
431	     */
432	    private int countNamesakes(String firstName, String lastName) {
433	        return (int) this.clinicService.findAllOwners().stream()
434	            .filter(existing -> existing.getFirstName() != null && existing.getLastName() != null)
435	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName)
436	                && existing.getLastName().equalsIgnoreCase(lastName))
437	            .count();
438	    }
439	
440	    /**
441	     * Count the existing owners that already belong to the given household (i.e. carry the same
442	     * non-null householdId). Called after any existing members have been backfilled with the shared
443	     * identifier but before the new owner is saved, so the returned value reflects the members that
444	     * already existed at creation time (the new owner itself is not included). Returns 0 when the
445	     * new owner is not part of any household ({@code householdId} is null).
446	     */
447	    private int countHouseholdMembers(String householdId) {
448	        if (householdId == null) {
449	            return 0;
450	        }
451	        return (int) this.clinicService.findAllOwners().stream()
452	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
453	            .count();
454	    }
455	
456	    /**
457	     * The maximum number of owners a single city may contain. Once a city holds this many owners a
458	     * request to create another owner in it is rejected as a conflict.
459	     */
460	    private static final int MAX_OWNERS_PER_CITY = 50;
461	
462	    /**
463	     * Count the existing owners registered in the given city, compared case-insensitively (as in
464	     * {@link #nextCustomerCode}). Called before the new owner is saved, so the returned value
465	     * reflects the owners that already existed at creation time.
466	     */
467	    private int countOwnersInCity(String city) {
468	        return (int) this.clinicService.findAllOwners().stream()
469	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
470	            .count();
471	    }
472	
473	    /**
474	     * The maximum number of owners that may be created on a single day. Once this many owners
475	     * already carry a given day's registration date, a request to create another owner that day is
476	     * rejected with a 429.
477	     */
478	    private static final int MAX_OWNERS_PER_DAY = 100;
479	
480	    /**
481	     * The number of owners that may be created on a single day before the bulk-signup warning is
482	     * flagged. Once more than this many owners already carry a given day's registration date, a
483	     * newly created owner is flagged with {@code bulkSignupWarning} set true.
484	     */
485	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
486	
487	    /**
488	     * Count the existing owners whose registration date is the given day. Called before the new
489	     * owner is saved, so the returned value reflects the owners that already existed at creation
490	     * time.
491	     */
492	    private int countOwnersRegisteredOn(LocalDate date) {
493	        return (int) this.clinicService.findAllOwners().stream()
494	            .filter(existing -> date.equals(existing.getRegistrationDate()))
495	            .count();
496	    }
497	
498	    /**
499	     * Roll a date forward onto a business day: a Saturday or Sunday is advanced to the following
500	     * Monday, while a weekday is returned unchanged. Used so the effective registration date (whether
501	     * supplied or defaulted) always falls on a business day.
502	     */
503	    private static LocalDate toBusinessDay(LocalDate date) {
504	        return switch (date.getDayOfWeek()) {
505	            case SATURDAY -> date.plusDays(2);
506	            case SUNDAY -> date.plusDays(1);
507	            default -> date;
508	        };
509	    }
510	
511	    private String nextCustomerCode(String city, String lastName) {
512	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
513	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
514	        long sequence = this.clinicService.findAllOwners().stream()
515	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
516	            .count() + 1L;
517	        return String.format("%s-%s-%04d", city3, last3, sequence);
518	    }
519	
520	    /**
521	     * The fixed city-to-region table used to validate a supplied postcode against the owner's city
522	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD). A city not present here has no known region
523	     * and accepts any 4-digit postcode.
524	     */
525	    private static final Map<String, String> CITY_REGION = Map.of(
526	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
527	
528	    /**
529	     * The fixed region-to-postcode ranges (inclusive): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099.
530	     * Each entry is a two-element {@code {low, high}} array.
531	     */
532	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
533	        "NSW", new int[] {2000, 2099},
534	        "VIC", new int[] {3000, 3099},
535	        "QLD", new int[] {4000, 4099});
536	
537	    /**
538	     * Validate an optional owner postcode. Does nothing when no postcode was supplied (the field is
539	     * optional and the request contract stays backward-compatible). When supplied it must be exactly
540	     * 4 digits and, if the city maps to a known region, must fall within that region's inclusive
541	     * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any
542	     * 4-digit postcode. A malformed or out-of-range postcode throws an
543	     * {@link InvalidOwnerFieldsException} so the request is rejected with a 400.
544	     */
545	    private static void validatePostcode(String city, String postcode) {
546	        if (postcode == null || postcode.isEmpty()) {
547	            return;
548	        }
549	        if (!postcode.matches("\\d{4}")) {
550	            throw new InvalidOwnerFieldsException(List.of("postcode"));
551	        }
552	        String region = city == null ? null : CITY_REGION.get(city);
553	        if (region == null) {
554	            return;
555	        }
556	        int[] range = REGION_POSTCODES.get(region);
557	        int value = Integer.parseInt(postcode);
558	        if (value < range[0] || value > range[1]) {
559	            throw new InvalidOwnerFieldsException(List.of("postcode"));
560	        }
561	    }
562	
563	    /**
564	     * Required national-number length for each E.164 country calling code we validate: a
565	     * {@code '+61'} (Australia) number carries 9 national digits and a {@code '+1'} (NANP) number
566	     * carries 10. Country codes not listed here are accepted at any (generally valid) length.
567	     */
568	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
569	        "1", 10,
570	        "61", 9);
571	
572	    /**
573	     * Convert a raw telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
574	     * {@code '+'} with its country code is preserved; otherwise the Australian country code
575	     * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national digits.
576	     * The result must be a {@code '+'} followed by 8 to 15 digits, and for a recognised country code
577	     * its national-number length must match ({@code '+61'} requires 9 national digits, {@code '+1'}
578	     * requires 10); otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is
579	     * rejected with a 400.
580	     */
581	    private static String toE164(String raw) {
582	        String cleaned = raw.trim().replaceAll("[\\s()\\-]", "");
583	        boolean hasCountryCode = cleaned.startsWith("+");
584	        String digits = hasCountryCode ? cleaned.substring(1) : cleaned;
585	        if (!digits.matches("\\d+")) {
586	            throw new InvalidOwnerFieldsException(List.of("telephone"));
587	        }
588	        if (!hasCountryCode) {
589	            if (digits.startsWith("0")) {
590	                digits = digits.substring(1);
591	            }
592	            digits = "61" + digits;
593	        }
594	        if (digits.length() < 8 || digits.length() > 15) {
595	            throw new InvalidOwnerFieldsException(List.of("telephone"));
596	        }
597	        // For a recognised country code, the national number (the digits after the code) must be
598	        // exactly the expected length for that country. Match the longest known code so a shorter
599	        // code that is a prefix of another cannot mask it.
600	        for (int codeLength = 3; codeLength >= 1; codeLength--) {
601	            if (digits.length() <= codeLength) {
602	                continue;
603	            }
604	            String countryCode = digits.substring(0, codeLength);
605	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
606	            if (requiredNationalLength != null) {
607	                if (digits.length() - codeLength != requiredNationalLength) {
608	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
609	                }
610	                break;
611	            }
612	        }
613	        return "+" + digits;
614	    }
615	
616	    /**
617	     * Pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
618	     * and a domain with at least one dot-separated label, none of which contain whitespace or
619	     * a second {@code @}. This is deliberately permissive but rejects obviously malformed input.
620	     */
621	    private static final Pattern EMAIL_PATTERN =
622	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
623	
624	    /**
625	     * Validate and normalize an optional owner email. Returns {@code null} when no email was
626	     * supplied (the field is optional). When supplied it must be a syntactically valid address,
627	     * otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a
628	     * 400. A valid address is returned lower-cased.
629	     */
630	    private static String normalizeEmail(String email) {
631	        if (email == null || email.isEmpty()) {
632	            return null;
633	        }
634	        String trimmed = email.trim();
635	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
636	            throw new InvalidOwnerFieldsException(List.of("email"));
637	        }
638	        return trimmed.toLowerCase();
639	    }
640	}
